script:
Create Variable Alpha Cost Keep;
Alpha = 0;
Cost = 0;
Keep = 41;
Earth.Mu = 398600.4415;
Create Spacecraft Sat;
Sat.DateFormat = UTCGregorian;
Sat.Epoch = '01 Jan 2000 12:00:00.000';
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = 7.5460532872678359;
Sat.VZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.Drag = None;
FM.SRP = Off;
Create Propagator P;
P.FM = FM;
P.InitialStepSize = 5;
P.MinStep = 5;
P.MaxStep = 5;
P.Accuracy = 1e-12;
Create FminconOptimizer Opt;
Opt.MaximumIterations = @ITERATIONS@;
Opt.MaxFunEvals = '@EVALUATIONS@';
Opt.TolX = '1e-9';
Opt.TolFun = '1e-10';
Opt.TolCon = '1e-10';
Opt.ShowProgress = false;
Opt.ReportFile = '@WORK@/Optimizer.txt';
Create ReportFile Trials;
Trials.Filename = '@WORK@/Trials.csv';
Trials.WriteHeaders = false;
Trials.FixedWidth = false;
Trials.Delimiter = ',';
Trials.Precision = 25;
Trials.SolverIterations = All;
Create EphemerisFile Export;
Export.Spacecraft = Sat;
Export.FileFormat = CCSDS-OEM;
Export.Filename = '@WORK@/Final.oem';
Export.CoordinateSystem = EarthMJ2000Eq;
Export.StepSize = IntegratorSteps;
Export.InterpolationOrder = 7;
BeginMissionSequence;
Optimize Opt {SolveMode = @MODE@, ExitMode = SaveAndContinue, ShowProgressWindow = false};
Vary Opt(Alpha = 0, {Lower = 0, Upper = 1, Perturbation = 0.0001, MaxStep = 0.5});
Cost = (Alpha-2)^2;
Sat.X = 7000+100*Alpha;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = sqrt(398600.4415/(7000+100*Alpha));
Sat.VZ = 0;
Report Trials Alpha Cost Keep;
Propagate P(Sat) {Sat.ElapsedSecs = 120};
Minimize Opt(Cost);
EndOptimize;
